import React from 'react';
import clsx from 'clsx';
import './AcidBadge.css';

export interface AcidBadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
    variant?: 'solid' | 'outline' | 'subtle' | 'brand';
    size?: 'sm' | 'md' | 'lg';
}

export const AcidBadge = React.forwardRef<HTMLSpanElement, AcidBadgeProps>(
    ({ className, variant = 'solid', size = 'md', children, ...props }, ref) => {
        return (
            <span
                ref={ref}
                className={clsx(
                    'ac-badge',
                    `ac-badge-${variant}`,
                    `ac-badge-${size}`,
                    className
                )}
                {...props}
            >
                {children}
            </span>
        );
    }
);

.ac-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-mono);
    font-weight: 700;
    white-space: nowrap;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-radius: var(--ac-radius-sm);
    transition: all 0.2s ease;
}

/* Sizes */
.ac-badge-sm {
    padding: 0 0.4rem;
    font-size: 0.65rem;
    height: 18px;
}

.ac-badge-md {
    padding: 0 0.6rem;
    font-size: 0.75rem;
    height: 24px;
}

.ac-badge-lg {
    padding: 0 0.8rem;
    font-size: 0.85rem;
    height: 30px;
}

/* Variants */
.ac-badge-solid {
    background: var(--ac-text-primary);
    color: var(--ac-bg);
}

.ac-badge-outline {
    background: transparent;
    color: var(--ac-text-primary);
    border: 1px solid var(--ac-border-bright);
}

.ac-badge-subtle {
    background: var(--ac-surface);
    color: var(--ac-text-secondary);
    border: 1px solid var(--ac-border-muted);
}

.ac-badge-brand {
    background: var(--ac-brand);
    color: #fff;
}
